package ru.neverland.townysieges;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.bukkit.configuration.file.YamlConfiguration;
public final class RaidLootSmoke {
    static int checks;static void ok(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
    static <T>T get(CompletionStage<T> f)throws Exception{return f.toCompletableFuture().get(10,TimeUnit.SECONDS);}static void close(RaidStore s)throws Exception{s.close();get(s.stopped());}
    public static void main(String[] args)throws Exception{
        var config=new YamlConfiguration();try(var in=RaidLootSmoke.class.getResourceAsStream("/config.yml")){config.load(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8));}
        var settings=LootSettings.load(config);var camps=CampSettings.load(config);ok(settings.moneyBps()==1000&&settings.resourcesBps()==1000,"default percentages 10/10");ok(camps.minimumArmy()==2&&camps.borderDistance()==16,"camp muster defaults");ok(LootSettings.share(100001,1000)==10000,"money rounds down to cents");ok(LootSettings.share(Long.MAX_VALUE,10000)==Long.MAX_VALUE,"percentage cannot overflow");
        for(Object invalid:List.of(-1,101,Double.NaN,1.001,"10")){config.set("loot.money-percent",invalid);try{LootSettings.load(config);throw new AssertionError("bad percentage");}catch(IllegalArgumentException expected){checks++;}}
        config.set("loot.money-percent",10);config.set("camp.minimum-army",0);try{CampSettings.load(config);throw new AssertionError("zero soldiers");}catch(IllegalArgumentException expected){checks++;}
        Path db=Files.createTempDirectory("raid-loot-smoke").resolve("raids.db");var s=new RaidStore(db,e->{throw new AssertionError(e);});get(s.ready());var journal=new RaidLootStore(s);
        UUID raid=UUID.randomUUID(),def=UUID.randomUUID(),att=UUID.randomUUID(),actor=UUID.randomUUID();long now=System.currentTimeMillis();get(s.start(new RaidStore.Raid(raid,att,def,actor,now-2000,now-1000,now+600000,now+86400000,"OPEN")));var permit=new RaidController.Permit(actor,att,def,raid,now,false);var key=new RaidStore.Key(UUID.randomUUID(),-1,160,16);
        var row=get(journal.arm(permit,key,new byte[]{1,2,3},settings));ok(row.state().equals("ARMED"),"capture intent durable before world mutation");var replay=get(journal.arm(new RaidController.Permit(UUID.randomUUID(),att,def,raid,now,false),key,new byte[0],settings));ok(replay.id().equals(row.id())&&replay.attacker().equals(att),"one reward per siege and defender, not per soldier");
        close(s);s=new RaidStore(db,e->{throw new AssertionError(e);});get(s.ready());journal=new RaidLootStore(s);row=get(journal.get(row.id()));ok(row.state().equals("REVIEW_CORE")&&Arrays.equals(row.book(),new byte[]{1,2,3}),"interrupted destruction retains book and requires confirmation");
        row=get(journal.resolve(row.id(),"core",true,"admin","checked native block history"));ok(row.state().equals("BREACHED"),"confirmed core releases capture once");row=get(journal.prepare(row.id(),10000,100000,10000));ok(row.cents()==10000,"frozen amounts saved");
        row=get(journal.bankStart(row.id(),"PREPARED",false,100000));close(s);s=new RaidStore(db,e->{throw new AssertionError(e);});get(s.ready());journal=new RaidLootStore(s);row=get(journal.get(row.id()));ok(row.state().equals("REVIEW_DEBIT"),"crash in bank withdrawal never auto-replays");
        row=get(journal.resolve(row.id(),"debit",true,"admin","bank debit receipt found"));row=get(journal.bankStart(row.id(),"DEBITED",true,10000));close(s);s=new RaidStore(db,e->{throw new AssertionError(e);});get(s.ready());journal=new RaidLootStore(s);row=get(journal.get(row.id()));ok(row.state().equals("REVIEW_CREDIT"),"crash in bank deposit never auto-replays");row=get(journal.resolve(row.id(),"credit",true,"admin","bank credit receipt found"));ok(row.state().equals("FUNDED"),"confirmed bank legs release only resource delivery");
        row=get(journal.change(row.id(),"FUNDED","DONE","resources=15"));ok(get(journal.list(true)).isEmpty(),"completed capture not automatically queued");ok(get(journal.arm(permit,key,new byte[0],settings)).state().equals("DONE"),"completed capture survives duplicate destruction");
        UUID another=UUID.randomUUID();ok(!RaidLootStore.operation(another,def).equals(row.id()),"new siege gets independent claim identity");close(s);
        System.out.println("RaidLootSmoke PASS: "+checks+" assertions; SQLite saga, crash points, review, book retention and unique capture");
    }
}
